    void DeviceRenderWorld::Initialize( TaskSystem* pTaskSystem, RenderSystem* pRenderSystem )
    {
        m_pTaskSystem = pTaskSystem;
        m_pRenderSystem = pRenderSystem;

        m_renderViews.m_storage.m_allocator.Initialize( 1 );
        m_skinningTransforms.m_storage.m_allocator.Initialize( 1 );

        m_meshInstanceRoots.m_storage.m_allocator.Initialize( 1 );
        m_decals.m_storage.m_allocator.Initialize( 1 );
        m_pointLights.m_storage.m_allocator.Initialize( 1 );
        m_spotLights.m_storage.m_allocator.Initialize( 1 );
        m_directionalLights.m_storage.m_allocator.Initialize( 1 );

        m_meshInstanceRoots.m_updateCommands.Initialize();
        m_meshInstanceUpdates.m_updatePool.Initialize();
        m_renderViews.m_updateCommands.Initialize();
        m_skinningTransforms.m_updateCommands.Initialize();

        m_decals.m_updateCommands.Initialize();
        m_pointLights.m_updateCommands.Initialize();
        m_spotLights.m_updateCommands.Initialize();
        m_directionalLights.m_updateCommands.Initialize();

        static StringID const s_InitializeInstancesShaderID = StringID( "InitializeInstances" );
        m_pInitializeInstancesShader = pRenderSystem->FindComputeShader( s_InitializeInstancesShaderID );

        static StringID const s_UpdateInstancesShaderID = StringID( "UpdateInstances" );
        m_pUpdateInstancesShader = pRenderSystem->FindComputeShader( s_UpdateInstancesShaderID );

        static StringID const s_ClusterToInstanceUpdateShaderID = StringID( "ClusterToInstanceUpdate" );
        m_pClusterToInstanceUpdateShader = pRenderSystem->FindComputeShader( s_ClusterToInstanceUpdateShaderID );

        for ( uint32_t frameIndex = 0; frameIndex < RHI::MaxPendingFrames; ++frameIndex )
        {
            m_meshInstanceRoots.m_storage.m_pageBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_meshInstanceInitialize.m_buffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_meshInstanceRoots.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_meshInstanceUpdates.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_skinningTransforms.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_renderViews.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );

            m_decals.m_storage.m_pageBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_decals.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_decalInitialize.m_buffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_pointLights.m_storage.m_pageBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_pointLights.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_pointLightInitialize.m_buffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_spotLights.m_storage.m_pageBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_spotLights.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_spotLightInitialize.m_buffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_directionalLights.m_storage.m_pageBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );
            m_directionalLights.m_updateCommands.m_updateBuffers[frameIndex].Initialize( pRenderSystem->GetContextRHI(), true );

            RHI::BufferParameters constantBufferParameters = {};
            constantBufferParameters.m_memoryType = RHI::ResourceMemoryType::HostToDevice;
            constantBufferParameters.m_bufferSize = sizeof( ShaderTypes::WorldUpdateConstants );
            constantBufferParameters.m_bufferStride = sizeof( ShaderTypes::WorldUpdateConstants );
            constantBufferParameters.m_flags = RHI::BufferFlags::PersistentMap;
            constantBufferParameters.m_descriptorTypes = RHI::DescriptorTypeFlags::ConstantBuffer;
            constantBufferParameters.m_debugName.sprintf( "DeviceRenderWorld WorldUpdate Constant Buffer %i", frameIndex );

            m_worldUpdateConstantBuffers[frameIndex] = RHI::CreateBuffer( pRenderSystem->GetContextRHI(), constantBufferParameters );
        }

        m_meshInstanceRoots.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );
        m_skinningTransforms.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );

        m_renderViews.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );

        m_decals.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );
        m_pointLights.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );
        m_spotLights.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );
        m_directionalLights.m_storage.m_instanceBuffer.Initialize( pRenderSystem->GetContextRHI(), true );

        m_meshInstanceBufferHandles.Initialize( pRenderSystem->GetContextRHI(), true );
        m_clusterToInstanceBufferHandles.Initialize( pRenderSystem->GetContextRHI(), true );

        //-------------------------------------------------------------------------

        EE_ASSERT( m_meshInstanceShaderPools.empty() );

        m_meshInstanceShaderPools.reserve( pRenderSystem->GetMaterialShaders().size() );
        for ( uint32_t shaderIndex = 0; shaderIndex < pRenderSystem->GetMaterialShaders().size(); ++shaderIndex )
        {
            m_meshInstanceShaderPools.emplace_back();
        }

        for ( MeshInstanceShaderPool& shaderPool : m_meshInstanceShaderPools )
        {
            shaderPool.m_instances.m_allocator.Initialize( 1 );
            shaderPool.m_clusterAllocator.Initialize( 1 );
            shaderPool.m_instances.m_instanceBuffer.Initialize( m_pRenderSystem->GetContextRHI(), true );
            shaderPool.m_clusterToInstanceBuffer.Initialize( m_pRenderSystem->GetContextRHI(), true );
            for ( uint32_t frameIndex = 0; frameIndex < RHI::MaxPendingFrames; ++frameIndex )
            {
                shaderPool.m_instances.m_pageBuffers[frameIndex].Initialize( m_pRenderSystem->GetContextRHI(), true );
            }
        }
    }

    void DeviceRenderWorld::Shutdown( RenderSystem* pRenderSystem )
    {
        EE_ASSERT( m_meshInstanceInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_pointLightInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_spotLightInitialize.m_copyCommands.GetIsComplete() );

        EE_ASSERT( m_meshInstanceRoots.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_meshInstanceUpdates.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_directionalLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_pointLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_spotLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_skinningTransforms.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_renderViews.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_decalInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_decals.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );

        m_meshInstanceRoots.m_storage.m_allocator.Shutdown();
        m_renderViews.m_storage.m_allocator.Shutdown();
        m_skinningTransforms.m_storage.m_allocator.Shutdown();

        m_decals.m_storage.m_allocator.Shutdown();
        m_pointLights.m_storage.m_allocator.Shutdown();
        m_spotLights.m_storage.m_allocator.Shutdown();
        m_directionalLights.m_storage.m_allocator.Shutdown();

        m_meshInstanceRoots.m_updateCommands.Shutdown();
        m_meshInstanceUpdates.m_updatePool.Shutdown();
        m_skinningTransforms.m_updateCommands.Shutdown();
        m_renderViews.m_updateCommands.Shutdown();

        m_decals.m_updateCommands.Shutdown();
        m_pointLights.m_updateCommands.Shutdown();
        m_spotLights.m_updateCommands.Shutdown();
        m_directionalLights.m_updateCommands.Shutdown();

        for ( uint32_t frameIndex = 0; frameIndex < RHI::MaxPendingFrames; ++frameIndex )
        {
            m_meshInstanceRoots.m_storage.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_meshInstanceInitialize.m_buffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_meshInstanceUpdates.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_meshInstanceRoots.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_skinningTransforms.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_renderViews.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );

            m_decals.m_storage.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_decals.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_decalInitialize.m_buffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_pointLights.m_storage.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_pointLights.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_pointLightInitialize.m_buffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_spotLights.m_storage.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_spotLights.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_spotLightInitialize.m_buffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_directionalLights.m_storage.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            m_directionalLights.m_updateCommands.m_updateBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );

            RHI::DestroyBuffer( pRenderSystem->GetContextRHI(), eastl::move( m_worldUpdateConstantBuffers[frameIndex] ) );
        }

        m_meshInstanceRoots.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
        m_skinningTransforms.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
        m_renderViews.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );

        m_decals.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
        m_pointLights.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
        m_spotLights.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
        m_directionalLights.m_storage.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );

        //-------------------------------------------------------------------------

        for ( MeshInstanceShaderPool& shaderPool : m_meshInstanceShaderPools )
        {
            shaderPool.m_instances.m_allocator.Shutdown();
            shaderPool.m_clusterAllocator.Shutdown();
            shaderPool.m_instances.m_instanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );
            shaderPool.m_clusterToInstanceBuffer.Shutdown( pRenderSystem->GetContextRHI() );

            for ( uint32_t frameIndex = 0; frameIndex < RHI::MaxPendingFrames; ++frameIndex )
            {
                shaderPool.m_instances.m_pageBuffers[frameIndex].Shutdown( pRenderSystem->GetContextRHI() );
            }
        }
        m_meshInstanceShaderPools.clear();

        m_meshInstanceBufferHandles.Shutdown( pRenderSystem->GetContextRHI() );

        m_clusterToInstanceBufferHandles.Shutdown( pRenderSystem->GetContextRHI() );

        //-------------------------------------------------------------------------

        m_pTaskSystem = nullptr;
        m_pRenderSystem = nullptr;
    }

    MeshInstanceRootProxy DeviceRenderWorld::AllocateMeshInstanceRoot()
    {
        HandleAllocator<uint32_t>::Handle meshInstanceRootHandle = m_meshInstanceRoots.Allocate( 1 );

        MeshInstanceRootProxy meshInstanceRootProxy = {};
        meshInstanceRootProxy.m_pTransformUpdateCounter = &m_meshInstanceRoots.m_updateCommands.m_updatePool.m_counter;
        meshInstanceRootProxy.m_pTransformUpdateSequence = &m_meshInstanceRoots.m_updateCommands.m_updatePool.m_sequence;
        meshInstanceRootProxy.m_pDstUpdateCommands = m_meshInstanceRoots.m_updateCommands.m_updatePool.m_memoryPool.GetData();
        meshInstanceRootProxy.m_instanceHandle = eastl::move( meshInstanceRootHandle );
        return meshInstanceRootProxy;
    }

    void DeviceRenderWorld::DeallocateMeshInstanceRoot( MeshInstanceRootProxy&& meshInstanceRootProxy )
    {
        m_meshInstanceRoots.m_storage.Deallocate( eastl::move( meshInstanceRootProxy.m_instanceHandle ) );
        meshInstanceRootProxy = {};
    }

    DeviceRenderWorld::MeshInstanceShaderPool& DeviceRenderWorld::GetMeshInstanceShaderPool( uint32_t shaderIndex )
    {
        EE_ASSERT( shaderIndex < m_meshInstanceShaderPools.size() );

        return m_meshInstanceShaderPools[shaderIndex];
    }

    MeshInstanceProxy DeviceRenderWorld::AllocateMeshInstance( uint32_t shaderIndex, TArrayView<uint32_t const> numClustersPerInstance )
    {
        EE_ASSERT( !numClustersPerInstance.empty() );

        MeshInstanceShaderPool& shaderPool = GetMeshInstanceShaderPool( shaderIndex );

        uint32_t numClusters = 0;
        for ( uint32_t instanceNumClusters : numClustersPerInstance )
        {
            numClusters += instanceNumClusters;
        }

        HandleAllocator<uint32_t>::Handle meshInstanceHandle = shaderPool.m_instances.Allocate( uint32_t( numClustersPerInstance.size() ) );
        EE_ASSERT( meshInstanceHandle.IsValid() );

        HandleAllocator<uint32_t>::Handle clustersHandle = {};
        if ( numClusters > 0 )
        {
            clustersHandle = shaderPool.m_clusterAllocator.Allocate( numClusters );
            EE_ASSERT( clustersHandle.IsValid() );
        }

        uint64_t totalInstanceCapacity = 0;
        for ( auto const& meshInstanceShaderPool : m_meshInstanceShaderPools )
        {
            totalInstanceCapacity += uint64_t( meshInstanceShaderPool.m_instances.GetCapacity() );
        }
        m_meshInstanceUpdates.m_updatePool.m_memoryPool.Commit( totalInstanceCapacity );

        MeshInstanceProxy meshInstanceProxy = {};
        meshInstanceProxy.m_pTransformUpdateCounter = &m_meshInstanceUpdates.m_updatePool.m_counter;
        meshInstanceProxy.m_pTransformUpdateSequence = &m_meshInstanceUpdates.m_updatePool.m_sequence;
        meshInstanceProxy.m_pDstTransformUpdateCommands = m_meshInstanceUpdates.m_updatePool.m_memoryPool.GetData();
        meshInstanceProxy.m_instanceHandle = eastl::move( meshInstanceHandle );
        meshInstanceProxy.m_clusterHandle = eastl::move( clustersHandle );
        meshInstanceProxy.m_shaderIndex = shaderIndex;
        return meshInstanceProxy;
    }

    void DeviceRenderWorld::DeallocateMeshInstance( MeshInstanceProxy&& meshInstanceProxy )
    {
        uint32_t const shaderIndex = meshInstanceProxy.m_shaderIndex;

        if ( meshInstanceProxy.m_clusterHandle.IsValid() )
        {
            MeshInstanceShaderPool& shaderPool = GetMeshInstanceShaderPool( shaderIndex );
            shaderPool.m_clusterAllocator.Deallocate( eastl::move( meshInstanceProxy.m_clusterHandle ) );
        }

        if ( meshInstanceProxy.m_instanceHandle.IsValid() )
        {
            MeshInstanceShaderPool& shaderPool = GetMeshInstanceShaderPool( shaderIndex );
            shaderPool.m_instances.Deallocate( eastl::move( meshInstanceProxy.m_instanceHandle ) );
        }

        meshInstanceProxy = {};
    }

