    void DeviceRenderWorld::DispatchWorldUpdate( RHI::CommandBuffer* pCommandBuffer, uint32_t frameIndex )
    {
        EE_ASSERT( m_meshInstanceInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_pointLightInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_spotLightInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_meshInstanceUpdates.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_meshInstanceRoots.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_directionalLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_pointLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_spotLights.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_skinningTransforms.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_renderViews.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );
        EE_ASSERT( m_decalInitialize.m_copyCommands.GetIsComplete() );
        EE_ASSERT( m_decals.m_updateCommands.m_copyUpdateCommands.GetIsComplete() );

        //-------------------------------------------------------------------------

        EE_RHI_COMMAND_BUFFER_PROFILE_SCOPE( pCommandBuffer, "DeviceRenderWorld Update" );

        //-------------------------------------------------------------------------

        bool hasTransformUpdateCommands = false;

        auto ScheduleUpdateCommands = [this, frameIndex, &hasTransformUpdateCommands] ( auto& updateCommands )
        {
            using UpdateCommands = std::remove_reference_t<decltype( updateCommands )>;
            using UpdateCommand = typename UpdateCommands::UpdateCommand;

            if ( updateCommands.m_updatePool.m_numUpdateCommands == 0 )
            {
                return;
            }

            hasTransformUpdateCommands = true;

            EE_ASSERT( updateCommands.m_updateBuffers[frameIndex].m_pBuffer->m_size >= size_t( updateCommands.m_updatePool.m_numUpdateCommands ) * sizeof( UpdateCommand ) );

            updateCommands.m_copyUpdateCommands.m_pSrcMemory = updateCommands.m_updatePool.m_memoryPool.GetData();
            updateCommands.m_copyUpdateCommands.m_pDstMemory_WriteCombined = static_cast<UpdateCommand*>( updateCommands.m_updateBuffers[frameIndex].m_pBuffer->m_pMappedAddress_WriteCombined );
            updateCommands.m_copyUpdateCommands.m_SetSize = updateCommands.m_updatePool.m_numUpdateCommands;
            updateCommands.m_copyUpdateCommands.m_MinRange = 1024;

            m_pTaskSystem->ScheduleTask( &updateCommands.m_copyUpdateCommands );
        };

        //-------------------------------------------------------------------------

        ScheduleUpdateCommands( m_renderViews.m_updateCommands );
        ScheduleUpdateCommands( m_decals.m_updateCommands );
        ScheduleUpdateCommands( m_meshInstanceUpdates );
        ScheduleUpdateCommands( m_meshInstanceRoots.m_updateCommands );
        ScheduleUpdateCommands( m_directionalLights.m_updateCommands );
        ScheduleUpdateCommands( m_pointLights.m_updateCommands );
        ScheduleUpdateCommands( m_spotLights.m_updateCommands );
        ScheduleUpdateCommands( m_skinningTransforms.m_updateCommands );

        //-------------------------------------------------------------------------

        bool hasInitCommands = false;

        auto ScheduleInitializeCommands = [this, frameIndex, &hasInitCommands] ( auto& initializeCommands )
        {
            using InitializeCommands = std::remove_reference_t<decltype( initializeCommands )>;
            using InitializeCommand = typename InitializeCommands::InitializeCommand;

            if ( initializeCommands.m_commands.empty() )
            {
                return;
            }

            hasInitCommands = true;

            RHI::Buffer* const pInitializeBuffer = initializeCommands.m_buffers[frameIndex].m_pBuffer;

            EE_ASSERT( ( pInitializeBuffer->m_size / pInitializeBuffer->m_stride ) >= initializeCommands.m_commands.size() );

            initializeCommands.m_copyCommands.m_pSrcMemory = initializeCommands.m_commands.data();
            initializeCommands.m_copyCommands.m_pDstMemory_WriteCombined = static_cast<InitializeCommand*>( pInitializeBuffer->m_pMappedAddress_WriteCombined );
            initializeCommands.m_copyCommands.m_SetSize = uint32_t( initializeCommands.m_commands.size() );
            initializeCommands.m_copyCommands.m_MinRange = 1024;

            m_pTaskSystem->ScheduleTask( &initializeCommands.m_copyCommands );
        };

        ScheduleInitializeCommands( m_meshInstanceInitialize );
        ScheduleInitializeCommands( m_pointLightInitialize );
        ScheduleInitializeCommands( m_spotLightInitialize );
        ScheduleInitializeCommands( m_decalInitialize );

        // World update constants
        //-------------------------------------------------------------------------

        uint32_t maxNumInitializeCommands = 0;
        uint32_t maxNumUpdateCommands = 0;
        {
            alignas( 32 ) ShaderTypes::WorldUpdateConstants worldUpdateConstants = {};
            worldUpdateConstants.m_numInitializeCommands_MeshInstance = uint32_t( m_meshInstanceInitialize.m_commands.size() );
            worldUpdateConstants.m_numInitializeCommands_PointLight = uint32_t( m_pointLightInitialize.m_commands.size() );
            worldUpdateConstants.m_numInitializeCommands_SpotLight = uint32_t( m_spotLightInitialize.m_commands.size() );
            worldUpdateConstants.m_numInitializeCommands_Decal = uint32_t( m_decalInitialize.m_commands.size() );
            worldUpdateConstants.m_numUpdateCommands_MeshInstanceRoot = m_meshInstanceRoots.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_MeshInstance = m_meshInstanceUpdates.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_DirectionalLight = m_directionalLights.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_PointLight = m_pointLights.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_SpotLight = m_spotLights.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_SkinningTransform = m_skinningTransforms.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_RenderView = m_renderViews.m_updateCommands.m_updatePool.m_numUpdateCommands;
            worldUpdateConstants.m_numUpdateCommands_Decal = m_decals.m_updateCommands.m_updatePool.m_numUpdateCommands;

            maxNumInitializeCommands = worldUpdateConstants.m_numInitializeCommands_MeshInstance;
            maxNumInitializeCommands = Math::Max( maxNumInitializeCommands, worldUpdateConstants.m_numInitializeCommands_PointLight );
            maxNumInitializeCommands = Math::Max( maxNumInitializeCommands, worldUpdateConstants.m_numInitializeCommands_SpotLight );
            maxNumInitializeCommands = Math::Max( maxNumInitializeCommands, worldUpdateConstants.m_numInitializeCommands_Decal );

            maxNumUpdateCommands = worldUpdateConstants.m_numUpdateCommands_MeshInstanceRoot;
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_MeshInstance );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_DirectionalLight );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_PointLight );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_SpotLight );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_SkinningTransform );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_RenderView );
            maxNumUpdateCommands = Math::Max( maxNumUpdateCommands, worldUpdateConstants.m_numUpdateCommands_Decal );

            Memory::CopyToWriteCombined( m_worldUpdateConstantBuffers[frameIndex]->m_pMappedAddress_WriteCombined, &worldUpdateConstants, sizeof( worldUpdateConstants ) );
        }

        // Instance initialize dispatch
        //-------------------------------------------------------------------------

        if ( hasInitCommands )
        {
            ShaderTypes::InitializeInstancesResourceTableData initializeInstancesResourceTable = {};

            initializeInstancesResourceTable.SetInitializeBuffer_MeshInstance( m_meshInstanceInitialize.m_buffers[frameIndex].m_pBuffer );
            initializeInstancesResourceTable.SetInitializeBuffer_PointLight( m_pointLightInitialize.m_buffers[frameIndex].m_pBuffer );
            initializeInstancesResourceTable.SetInitializeBuffer_SpotLight( m_spotLightInitialize.m_buffers[frameIndex].m_pBuffer );
            initializeInstancesResourceTable.SetInitializeBuffer_Decal( m_decalInitialize.m_buffers[frameIndex].m_pBuffer );

            initializeInstancesResourceTable.SetMeshInstanceBufferHandles( m_meshInstanceBufferHandles.m_pBuffer );
            initializeInstancesResourceTable.SetPointLightBuffer( m_pointLights.m_storage.m_instanceBuffer.m_pBuffer );
            initializeInstancesResourceTable.SetSpotLightBuffer( m_spotLights.m_storage.m_instanceBuffer.m_pBuffer );
            initializeInstancesResourceTable.SetDecalBuffer( m_decals.m_storage.m_instanceBuffer.m_pBuffer );

            RHI::CmdSetPipeline( pCommandBuffer, m_pInitializeInstancesShader->m_pPipeline );
            RHI::CmdSetRootConstants( pCommandBuffer, 0, &initializeInstancesResourceTable, sizeof( initializeInstancesResourceTable ) );
            RHI::CmdSetRootParameter( pCommandBuffer, 1, m_worldUpdateConstantBuffers[frameIndex], 0 );
            RHI::CmdDispatchCompute( pCommandBuffer, ( maxNumInitializeCommands + 63 ) / 64, 1, 1 );
            RHI::CmdBarrier( pCommandBuffer, RHI::PipelineStage::ComputeShader, RHI::PipelineStage::ComputeShader, RHI::ResourceAccess::UnorderedAccess, RHI::ResourceAccess::UnorderedAccess );

            //-------------------------------------------------------------------------

            if ( !m_meshInstanceInitialize.m_commands.empty() )
            {
                ShaderTypes::ClusterToInstanceUpdateResourceTableData clusterToInstanceUpdateResourceTable = {};
                clusterToInstanceUpdateResourceTable.SetInitializeBuffer_MeshInstance( m_meshInstanceInitialize.m_buffers[frameIndex].m_pBuffer );
                clusterToInstanceUpdateResourceTable.SetClusterToInstanceBufferHandles( m_clusterToInstanceBufferHandles.m_pBuffer );

                RHI::CmdSetPipeline( pCommandBuffer, m_pClusterToInstanceUpdateShader->m_pPipeline );
                RHI::CmdSetRootConstants( pCommandBuffer, 0, &clusterToInstanceUpdateResourceTable, sizeof( clusterToInstanceUpdateResourceTable ) );
                RHI::CmdDispatchCompute( pCommandBuffer, uint32_t( m_meshInstanceInitialize.m_commands.size() ), 1, 1 );
            }

            RHI::CmdBarrier( pCommandBuffer, RHI::PipelineStage::ComputeShader, RHI::PipelineStage::AllShader, RHI::ResourceAccess::UnorderedAccess, RHI::ResourceAccess::ShaderResource );
        }

        // Transform update dispatch
        //-------------------------------------------------------------------------

        if ( hasTransformUpdateCommands )
        {
            ShaderTypes::UpdateInstancesResourceTableData updateInstancesResourceTable = {};

            updateInstancesResourceTable.SetUpdateBuffer_MeshInstanceRoot( m_meshInstanceRoots.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_MeshInstance( m_meshInstanceUpdates.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_DirectionalLight( m_directionalLights.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_PointLight( m_pointLights.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_SpotLight( m_spotLights.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_SkinningTransform( m_skinningTransforms.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_RenderView( m_renderViews.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );
            updateInstancesResourceTable.SetUpdateBuffer_Decal( m_decals.m_updateCommands.m_updateBuffers[frameIndex].m_pBuffer );

            updateInstancesResourceTable.SetSkinningTransformBuffer( m_skinningTransforms.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetMeshInstanceRootBuffer( m_meshInstanceRoots.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetMeshInstanceBufferHandles( m_meshInstanceBufferHandles.m_pBuffer );
            updateInstancesResourceTable.SetDirectionalLightBuffer( m_directionalLights.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetPointLightBuffer( m_pointLights.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetSpotLightBuffer( m_spotLights.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetRenderViewBuffer( m_renderViews.m_storage.m_instanceBuffer.m_pBuffer );
            updateInstancesResourceTable.SetDecalBuffer( m_decals.m_storage.m_instanceBuffer.m_pBuffer );

            RHI::CmdSetPipeline( pCommandBuffer, m_pUpdateInstancesShader->m_pPipeline );
            RHI::CmdSetRootConstants( pCommandBuffer, 0, &updateInstancesResourceTable, sizeof( updateInstancesResourceTable ) );
            RHI::CmdSetRootParameter( pCommandBuffer, 1, m_worldUpdateConstantBuffers[frameIndex], 0 );
            RHI::CmdDispatchCompute( pCommandBuffer, ( maxNumUpdateCommands + 63 ) / 64, 1, 1 );

            RHI::CmdBarrier( pCommandBuffer, RHI::PipelineStage::ComputeShader, RHI::PipelineStage::AllShader, RHI::ResourceAccess::UnorderedAccess, RHI::ResourceAccess::ShaderResource );
        }

        if ( hasTransformUpdateCommands )
        {
            m_meshInstanceRoots.m_updateCommands.Submit();
            m_meshInstanceUpdates.m_updatePool.Submit();
            m_skinningTransforms.m_updateCommands.Submit();
            m_renderViews.m_updateCommands.Submit();

            m_decals.m_updateCommands.Submit();
            m_pointLights.m_updateCommands.Submit();
            m_spotLights.m_updateCommands.Submit();
            m_directionalLights.m_updateCommands.Submit();
        }

        //-------------------------------------------------------------------------

        for ( MeshInstanceShaderPool& shaderPool : m_meshInstanceShaderPools )
        {
            shaderPool.m_instances.UpdatePageBuffer( frameIndex );
        }

        m_meshInstanceRoots.m_storage.UpdatePageBuffer( frameIndex );
        m_decals.m_storage.UpdatePageBuffer( frameIndex );
        m_pointLights.m_storage.UpdatePageBuffer( frameIndex );
        m_spotLights.m_storage.UpdatePageBuffer( frameIndex );
        m_directionalLights.m_storage.UpdatePageBuffer( frameIndex );
    }

    void DeviceRenderWorld::WaitForCopyTasks( RenderSystem* pRenderSystem )
    {
        uint32_t            frameIndex = pRenderSystem->GetFrameIndex();
        RHI::Context*       pContextRHI = pRenderSystem->GetContextRHI();

        //-------------------------------------------------------------------------

        m_pTaskSystem->WaitForTask( &m_meshInstanceInitialize.m_copyCommands );
        m_pTaskSystem->WaitForTask( &m_pointLightInitialize.m_copyCommands );
        m_pTaskSystem->WaitForTask( &m_spotLightInitialize.m_copyCommands );
        m_pTaskSystem->WaitForTask( &m_meshInstanceRoots.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_meshInstanceUpdates.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_directionalLights.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_pointLights.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_spotLights.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_skinningTransforms.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_renderViews.m_updateCommands.m_copyUpdateCommands );
        m_pTaskSystem->WaitForTask( &m_decalInitialize.m_copyCommands );
        m_pTaskSystem->WaitForTask( &m_decals.m_updateCommands.m_copyUpdateCommands );

        Memory::WriteCombinedBarrier();

        m_meshInstanceInitialize.Clear();

        m_pointLightInitialize.Clear();
        m_spotLightInitialize.Clear();
        m_decalInitialize.Clear();
    }

